// ❌ Inheritance for reuse: every discount type becomes a subclass,
// and DiscountCalculator itself must change to add each one.
public class DiscountCalculator {
    public decimal Apply(Order order) => order.Total;
}
public class PercentageDiscount : DiscountCalculator { /* ... */ }
public class FixedDiscount : DiscountCalculator { /* ... */ }
public class BuyOneGetOne : DiscountCalculator { /* ... */ }

// ✅ Composition: the calculator is stable; strategies are plug-ins.
public interface IDiscountStrategy {
    decimal Apply(Order order);
}

public sealed class PercentageDiscount(decimal percent) : IDiscountStrategy {
    public decimal Apply(Order order) => order.Total * (1 - percent);
}

public sealed class PercentageWithCap(decimal percent, decimal cap) : IDiscountStrategy {
    public decimal Apply(Order order)
        => Math.Min(order.Total * (1 - percent), order.Total - cap);
}

public sealed class OrderPricing(IReadOnlyList<IDiscountStrategy> strategies) {
    public decimal TotalFor(Order order) {
        var total = order.Total;
        foreach (var s in strategies) total = s.Apply(order);
        return total;
    }
}
// New rule = new class. Existing classes untouched (Open/Closed),
// and strategies can be combined, unit-tested, and swapped per tenant.
